import sys; sys.path.insert(0, sys.argv[1]); from batch_lib import write_batch
# (id, name, kind, x, y, roots, description, subs, links, person, activity)
P=[
('calle_inchiostro',"Calle dell'Inchiostro",'site',41,47,['marre_palace','o_cerdans'],"A narrow lane behind the Piazza where scriveners copy for the Council and the Cerdans by the page. Every window has a desk in it and every desk a lamp.",
 [('desks','The Copy-Desks','Rows of slanted desks, and nobody speaking.'),('stair','The Paper Stair','Bales of rag-paper stacked to the landing.')],['marre_palace'],
 ('tonina','Tonina Sgarb','Scrivener of the Calle','a woman with a black thumb and a pen behind each ear',"She blots the line before she looks up. “Tonina Sgarb. I copy what I am given and forget it by supper. That is the trade.”","Tonina can tell a clerk of the Council from a clerk of the Cerdans by the paper they bring.","“A fair hand is worth more than a fair face here,” Tonina says. “Faces change at Carnevale.”",'desks','stair'),
 ('copy_fair','Copy a page fair','A page of someone else’s words, set down without one of your own.','desks',8,17,2,'skill_letters',None)),
('molo_grano','Molo del Grano','site',46,41,['marre_palace'],"The quay at the lagoon end of the Piazza where the grain barges tie up. The Republic counts every sack ashore, because a hungry city is not a serene one.",
 [('quay','The Grain Quay','Barges three deep, and a plank to each.'),('measure','The Measuring Shed','Bronze measures chained to the wall, stamped with the lion.')],['marre_palace'],
 ('bortolo','Bortolo Pes','Measurer of Grain','a broad man with chaff in his beard and a tally-board on a cord',"“Stand off the plank,” he says, and then, when the sack has passed: “Bortolo Pes. I measure. The Republic believes me, so the bargemen must.”","Bortolo says the barges ride lower in a good year, and that he can read the harvest from the bridge.","“Level measure,” Bortolo says. “Not heaped, not shaken. Level.”",'quay','measure'),
 ('carry_grain','Carry sacks ashore','Down the plank with a sack on your shoulder, and the measurer counting.','quay',6,14,2,'skill_athletics',None)),
('campo_leoni','Campo dei Due Leoni','site',42,41,['marre_palace','c_dolma'],"A small square behind the Basilica where the lion-keepers of the Serene Matron live. Two worn stone lions sit at its well, copies of the glass ones nobody may touch.",
 [('well','The Lion Well','A well-head between two stone lions, their noses rubbed smooth.'),('houses','The Keepers’ Houses','A row of narrow houses, each with a green lamp.')],['marre_palace'],
 ('marietta','Marietta Zan','Lion-Keeper of the Matron','an old woman polishing a stone lion with her sleeve',"“Rub his nose,” she says. “This one you may.” She watches you do it. “Marietta Zan. I keep the glass ones. These keep me.”","Marietta has dusted the sleeping lion every morning for forty years and says he has never once stirred.","“One awake, one asleep,” Marietta says. “That is how to run a city.”",'well','houses'),
 ('trim_lamps','Trim the green lamps','Wick, oil and glass, house by house round the square.','houses',16,20,1,'skill_devotion',None)),
('riva_ombra',"Riva dell'Ombra",'site',47,46,['marre_palace'],"The shaded quay under the palace roof, where families wait in boats for word of someone in the Leads. Nobody raises their voice here.",
 [('steps','The Water-Steps','Green steps, and boats that do not tie up.'),('grating','The Low Grating','A barred window at the waterline, for parcels.')],['marre_palace','marre_city'],
 ('nane','Nane Tosat','Boatman of the Riva','a boatman resting on his oar with his cap over his eyes',"He lifts the cap an inch. “Nane Tosat. I carry bread in and letters out. I do not read either.”","Nane knows which families have been waiting a week and which a year, by where they moor.","“In summer the roof is the punishment,” Nane says. “The judge only chooses how long.”",'steps','grating'),
 ('carry_parcels','Carry parcels to the grating','Bread, a clean shirt, a note folded small. Hand each one in and say the name.','steps',7,18,1,'skill_seamanship',None)),
('osteria_bauta','Osteria della Bauta','site',45,49,['marre_palace','o_cerdans'],"A wine-shop a bridge away from the black door, where informers drink and are careful what about. Its sign is a white mask with no mouth.",
 [('taproom','The Front Room','Low benches, spiced wine and long silences.'),('snug','The Room Behind','One table, one lamp, and a door to the canal.')],['marre_palace','marre_city'],
 ('catina','Catina Fol','Keeper of the Bauta','a woman who fills your cup without asking and listens without seeming to',"She sets the cup down. “Catina Fol. Drink, pay, and talk about the weather. Everyone here does.”","Catina can tell who is watching whom by which bench they choose.","“I hear nothing,” Catina says. “I am paid twice for it.”",'taproom','snug'),
 ('listen_benches','Listen along the benches','A cup that lasts an hour, and both ears open.','taproom',18,23,2,'skill_streetwise',12)),
('squero_storto','Squero Storto','site',53,56,['marre_city'],"A boatyard on a bent side-canal where gondolas are built by eye, each a hand’s breadth crooked so that one oar drives it straight.",
 [('slip','The Slip','A black hull on trestles, and pitch on the boil.'),('loft','The Rib Loft','Oak ribs hung to season, each chalked with a name.')],['marre_city'],
 ('menego','Menego Rui','Boatwright of the Squero','a man sighting along a plank with one eye shut',"“Crooked,” he says, pleased, and puts the plank down. “Menego Rui. If it were straight it would go in circles.”","Menego builds one boat in a season and says the Arsenal builds a galley a day because nobody has to love a galley.","“Eight woods in a gondola,” Menego says. “And one man’s temper.”",'slip','loft'),
 ('pitch_hull','Pitch a hull','Hot pitch and a long brush, seam by seam.','slip',7,16,2,'skill_woodwork',None)),
('pescaria','The Pescaria','site',58,49,['marre_city'],"The fish market by the Rialto, loud before dawn and washed down by the third hour. Everything on the slabs was in the lagoon yesterday.",
 [('slabs','The Slabs','Marble slabs, running water and silver heaps.'),('boats','The Night Boats','Fishing boats unloading by lantern.')],['marre_city','marre_canal'],
 ('betta','Betta Guss','Fishwife of the Pescaria','a woman gutting sardines faster than you can count them',"“Fresh,” she says, before you ask. “Betta Guss. If it winks at you it is too fresh.”","Betta knows which cook buys for which palazzo, and what each house is eating less of this month.","“The Ten Families eat what I say is good,” Betta says. “They think their cooks choose.”",'slabs','boats'),
 ('gut_sardines','Gut sardines','Thumb in, thumb out, into the basket. Mind the knife.','slabs',6,10,2,'skill_fishing',None)),
('corte_tinta','Corte della Tinta','site',59,55,['marre_city'],"A dyers’ court where the canal runs three colours by noon. Silk from the Terraferma comes in white and leaves in the colours of the great houses.",
 [('vats','The Vats','Steaming vats, and arms stained to the elbow.'),('lines','The Drying Lines','Silk hung across the court like flags.')],['marre_city'],
 ('zuane','Zuane Tinto','Dyer of the Corte','a man whose hands are blue to the wrist and red above it',"He holds up both hands. “Zuane Tinto. Do not shake them. It does not come off.”","Zuane will not say which house’s colour is hardest to match, only that one of them never pays on time.","“Every house has a colour,” Zuane says. “I am the only man in Marre who wears them all.”",'vats','lines'),
 ('stir_vats','Stir the vats','A long paddle, slow and even, or the colour takes in streaks.','vats',6,15,2,'skill_clothwork',None)),
('ponte_maschere','Ponte delle Maschere','site',62,50,['marre_city','marre_canal'],"A covered bridge of mask-makers’ stalls between the city and the great palazzi. A hundred white faces hang in every window.",
 [('stalls','The Stalls','Masks drying on pegs, gilt and plain.'),('span','The Span','The crown of the bridge, and the best view of who is going where.')],['marre_city','marre_canal'],
 ('lucieta','Lucieta Bas','Mask-Maker of the Ponte','a young woman painting a white mask with a brush of three hairs',"“Hold still,” she says, and measures your face with her thumb. “Lucieta Bas. You would suit a plain one. Most people do.”","Lucieta remembers every face she has fitted, which is more than her customers would like.","“By law nobody may ask who you are in a mask,” Lucieta says. “Nobody said I could not know.”",'stalls','span'),
 ('gild_masks','Gild a row of masks','Size, leaf, and a breath to lay it. Do not sneeze.','stalls',9,18,2,'skill_stagecraft',12)),
('fondamenta_specchi','Fondamenta degli Specchi','site',70,42,['marre_canal','marre_isles'],"The mirror-sellers’ quay, facing the Glass Isles across the water. The glass comes over by guarded barge; the men who made it do not.",
 [('shops','The Mirror Shops','Shop after shop of your own face.'),('landing','The Guarded Landing','Where the glass barges unload under seal.')],['marre_canal'],
 ('anzolo','Anzolo Fri','Mirror-Dealer of the Fondamenta','a thin man who looks at your reflection instead of at you',"He speaks to the glass. “Anzolo Fri. Every mirror here is honest. That is why they are dear.”","Anzolo can name the master of any mirror by the colour of its silver.","“A cheap mirror flatters,” Anzolo says. “Ours do not, and people pay for it. Explain that.”",'shops','landing'),
 ('polish_mirrors','Polish the stock','Chalk and a soft cloth, in circles, until you can see what you would rather not.','shops',8,17,1,'skill_trade',None)),
('waiting_roads','The Waiting Roads','site',27,58,['lazaretto'],"The anchorage off the Lazaretto where ships from the east ride out their forty days. From the island they look like a town that is not allowed ashore.",
 [('anchorage','The Anchorage','Ships at two anchors, hatches open to the air.'),('guardboat','The Health Boat','A grey boat that rows the line at dawn and dusk.')],['lazaretto'],
 ('stae','Stae Dolfi','Oarsman of the Health Boat','a sunburnt man who keeps an oar’s length from everyone',"He holds up a hand before you come closer. “Stae Dolfi. I row the officers round. Stay upwind and we shall get on.”","Stae counts days for forty ships at once and has never been wrong by one.","“Day thirty-nine is the long one,” Stae says.",'guardboat','anchorage'),
 ('row_line','Row the line','Ship to ship at an oar’s length, while the officer calls up his questions.','guardboat',5,9,2,'skill_seamanship',None)),
('quiet_isle','The Quiet Isle','site',20,66,['lazaretto'],"A low island south of the Lazaretto where its dead are buried in lime. One man lives on it and keeps the list.",
 [('pits','The Lime Pits','Long white trenches, and gulls that will not land.'),('hut','The List-Keeper’s Hut','A hut, a ledger and a bell.')],['lazaretto'],
 ('tita','Tita Nard','Corpse-Bearer of the Quiet Isle','a big, gentle man with lime on his boots and a ledger under his arm',"He takes off his cap. “Tita Nard. I write them all down. Somebody comes asking, in the end.”","Tita says the island is the only place in the lagoon where nobody lies to him.","“A name and a day,” Tita says. “It is not much. It is more than the sea gives.”",'pits','hut'),
 ('keep_list','Keep the list','Name, ship and day, in a fair hand, and the bell rung once for each.','hut',7,16,1,'skill_letters',None)),
('isle_of_simples','The Isle of Simples','site',28,66,['lazaretto'],"A walled physic garden on its own islet, which grows what the Spezieria cannot wait a season’s sailing for.",
 [('beds','The Physic Beds','Square beds, each with a slate.'),('stillroom','The Still-Room','Copper stills and a smell that clears the head.')],['lazaretto'],
 ('agnesina','Agnesina Rov','Herb-Wife of the Simples','a small woman in a straw hat, crushing a leaf under your nose',"“Smell,” she says. “Now you will not forget it. Agnesina Rov. Half of physic is not picking the wrong one.”","Agnesina sends a basket to the wards every dawn and gets it back empty every dusk.","“The fever-bark comes from across the sea,” Agnesina says. “Everything else comes from me.”",'beds','stillroom'),
 ('gather_simples','Gather simples','The right leaf at the right hour, into the right basket.','beds',6,11,1,'skill_herblore',12)),
('stilt_huts','The Stilt Huts','site',36,54,['marre_palace','lazaretto'],"Fishermen’s huts on stilts in the middle of the lagoon, an hour from anywhere. The eel-men live on them from spring to autumn.",
 [('platform','The Net Platform','Nets drying, and a brazier on a slate.'),('traps','The Eel Traps','Wicker traps on a line, lifted at dusk.')],['marre_palace','lazaretto'],
 ('checo','Checo Bisat','Eel-Man of the Shallows','a wiry man hauling a wicker trap hand over hand',"“Wet feet,” he says, looking at yours. “Checo Bisat. Sit on the dry side. There is one.”","Checo knows the lagoon’s channels by the colour of the water and has never owned a chart.","“The city thinks the lagoon is its moat,” Checo says. “It is its larder.”",'platform','traps'),
 ('lift_traps','Lift the eel traps','Hand over hand up the line, and a quick grip behind the head.','traps',16,20,2,'skill_fishing',None)),
('pilots_rest',"Pilots' Rest",'site',34,70,['lazaretto','wp_lighthouse'],"The pilot station at the lagoon mouth. No ship crosses the bar without a Marrean pilot, and the Republic means it that way.",
 [('lookout','The Lookout','A tower of four poles and a platform.'),('boathouse','The Boathouse','Six-oared pilot boats, kept wet.')],['lazaretto','wp_lighthouse'],
 ('iseppo','Iseppo Lanz','Pilot of the Bar','a grey man watching the water as if it owed him money',"He does not turn round. “Iseppo Lanz. The bar moved a boat’s length last winter. Nobody told the charts.”","Iseppo has brought in every spice-galley for twenty autumns and says they ride lower each year.","“A foreign captain asks how deep,” Iseppo says. “A wise one asks me to take the helm.”",'lookout','boathouse'),
 ('sound_channel','Sound the channel','Lead over the bow, call the mark, and again.','boathouse',6,15,2,'skill_seamanship',12)),
('barge_stair','The Barge Stair','site',14,44,['terraferma'],"The landing where the mainland barges load for the city: rice, silk, firewood and wine, and the Families going out to their villas in summer.",
 [('stair','The Stair','Wide stone steps, half of them under water.'),('sheds','The Toll Sheds','Where every bale is counted for the Republic.')],['terraferma','stilt_huts'],
 ('gasparo','Gasparo Ton','Barge-Master of the Stair','a heavy man shouting at a barge as if it could hear',"He stops shouting to look you over. “Gasparo Ton. If it floats and it is slow, it is mine.”","Gasparo says the city would starve in a week without his barges and has said so to a senator.","“Glass goes out on galleys,” Gasparo says. “Supper comes in on me.”",'stair','sheds'),
 ('load_barge','Load a barge','Bales to the plank, plank to the hold, and trim her level.','stair',6,16,2,'skill_athletics',None)),
('silk_sheds','The Silk Sheds','village',10,36,['terraferma'],"A hamlet among the mulberry groves where the worms are fed day and night for six weeks, and the whole place holds its breath.",
 [('sheds','The Worm Sheds','Trays to the rafters, and a sound like rain.'),('reels','The Reeling Yard','Cauldrons, cocoons and women with quick fingers.')],['terraferma'],
 ('orsetta','Orsetta Brun','Silk-Wife of the Sheds','a woman carrying a tray of leaves as if it were asleep',"“Softly,” she says. “They can hear you.” She sets the tray down. “Orsetta Brun. No shouting, no smoke, no thunder if you can help it.”","Orsetta has not slept a whole night in silk season since she was a girl.","“The city wears it,” Orsetta says. “We raise it. Ask which is harder.”",'sheds','reels'),
 ('feed_worms','Feed the worms','Fresh leaves on every tray, the old ones lifted away, and not a sound.','sheds',5,21,2,'skill_husbandry',None)),
('chiusa_vecchia','Chiusa Vecchia','site',6,46,['terraferma'],"The old sluice that floods the rice-fields in spring and drains them for harvest. Its keeper decides whose field drinks first.",
 [('gates','The Sluice Gates','Black oak gates and a wheel two men can barely turn.'),('dyke','The Dyke Path','A raised path between water and water.')],['terraferma'],
 ('bepi','Bepi Sguaz','Keeper of the Chiusa','a man in mud to the knee with a heron standing beside him',"“Mind the heron,” he says. “He was here first. Bepi Sguaz. I let the water in and I let it out.”","Bepi is offered a bribe by every farmer each spring and takes them all, in order.","“Water is patient,” Bepi says. “Farmers are not. I stand between.”",'gates','dyke'),
 ('turn_wheel','Turn the sluice wheel','Shoulder to the spoke, and round, and the gate comes up a finger.','gates',6,12,1,'skill_athletics',None)),
('ash_isle','Ash Isle','site',82,36,['marre_isles'],"A grey islet off the Glass Isles where the furnaces’ ash and broken glass are tipped. Pickers sift it for cullet to sell back.",
 [('tips','The Tips','Grey heaps that glitter when the sun is low.'),('sieves','The Sieves','Long sieves on trestles, and bandaged hands.')],['marre_isles'],
 ('nineta','Nineta Scoa','Cullet-Picker of Ash Isle','a young woman with rag-bound hands and a sack that clinks',"She shakes the sack at you. “Nineta Scoa. Do not pick anything up. You will bleed, and then you will know why.”","Nineta can tell which furnace a shard came from by its green.","“They burn it, they break it, they buy it back,” Nineta says. “I am the only one who gets paid twice.”",'tips','sieves'),
 ('sift_cullet','Sift for cullet','Shake the sieve, pick the glass, and keep your fingers.','sieves',7,17,2,'skill_kilncraft',None)),
('guard_boats','The Guard Boats','site',74,36,['marre_isles','marre_canal'],"The station of the boats that circle the Glass Isles day and night. They are there to keep pirates out, the Republic says.",
 [('pontoon','The Pontoon','Four black boats and a brazier.'),('watch','The Watch-Hut','A slate of names, each crossed off at dusk.')],['marre_isles','fondamenta_specchi'],
 ('vettor','Vettor Stagn','Captain of the Guard Boats','a patient man counting lit windows on the far shore',"He finishes counting first. “Vettor Stagn. Every master is at his furnace tonight. That is all I am asked.”","Vettor has rowed round the Isles for eleven years and knows every glassmaker by his silhouette.","“They are the richest prisoners in the world,” Vettor says. “I am the poorest gaoler.”",'pontoon','watch'),
 ('row_circuit','Row the circuit','Once round the Isles, slowly, counting lamps.','pontoon',18,23,3,'skill_seamanship',None)),
]
write_batch(sys.argv[2] if len(sys.argv) > 2 else '.', 'marre', 'marre-01', P, "Marre, first batch: twenty small places round the Piazza, the city, the Lazaretto, the mainland and the Glass Isles.", water=True)
